{
  "alert": "Payments-api error log rate above 1%",
  "alertType": "LOGS_BASED_ALERT",
  "annotations": {
    "description": "Error log rate in {{$deployment.environment}} is {{$value}}%",
    "summary": "Payments-api error rate above {{$threshold}}%"
  },
  "condition": {
    "compositeQuery": {
      "panelType": "graph",
      "queries": [
        {
          "spec": {
            "aggregations": [
              {
                "expression": "count()"
              }
            ],
            "disabled": true,
            "filter": {
              "expression": "service.name = 'payments-api' AND severity_text IN ['ERROR', 'FATAL']"
            },
            "groupBy": [
              {
                "fieldContext": "resource",
                "fieldDataType": "string",
                "name": "deployment.environment"
              }
            ],
            "name": "A",
            "signal": "logs",
            "stepInterval": 60
          },
          "type": "builder_query"
        },
        {
          "spec": {
            "aggregations": [
              {
                "expression": "count()"
              }
            ],
            "disabled": true,
            "filter": {
              "expression": "service.name = 'payments-api'"
            },
            "groupBy": [
              {
                "fieldContext": "resource",
                "fieldDataType": "string",
                "name": "deployment.environment"
              }
            ],
            "name": "B",
            "signal": "logs",
            "stepInterval": 60
          },
          "type": "builder_query"
        },
        {
          "spec": {
            "expression": "(A / B) * 100",
            "legend": "{{deployment.environment}}",
            "name": "F1"
          },
          "type": "builder_formula"
        }
      ],
      "queryType": "builder",
      "unit": "percent"
    },
    "selectedQueryName": "F1",
    "thresholds": {
      "kind": "basic",
      "spec": [
        {
          "channels": [
            "slack-payments"
          ],
          "matchType": "at_least_once",
          "name": "critical",
          "op": "above",
          "target": 1
        }
      ]
    }
  },
  "description": "Error log ratio as a percentage of total logs for payments-api",
  "evaluation": {
    "kind": "rolling",
    "spec": {
      "evalWindow": "5m",
      "frequency": "1m"
    }
  },
  "labels": {
    "severity": "critical",
    "team": "payments"
  },
  "notificationSettings": {
    "groupBy": [
      "deployment.environment"
    ],
    "renotify": {
      "alertStates": [
        "firing"
      ],
      "enabled": true,
      "interval": "30m"
    }
  },
  "ruleType": "threshold_rule",
  "schemaVersion": "v2alpha1",
  "version": "v5"
}

